SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ccb912028d375a202ec5b8e1e2979ec4bc1b9c7a/content/books/zizhi-tongjian/vol-293/year-0957/part-05/sources/library/jiuwudaishi-117-november-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002776；EPUB电子本，纸本及异文待核", "id": "2985c070-3cf4-52a9-99d9-7b31623e8db2"}, {"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ccb912028d375a202ec5b8e1e2979ec4bc1b9c7a/content/books/zizhi-tongjian/vol-293/year-0957/part-05/sources/library/jiuwudaishi-117-october-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002775；EPUB电子本，纸本及异文待核", "id": "86de14bb-8e5c-5482-86a2-ea7fa5240764"}, {"title": "宋史·巻二百六十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ccb912028d375a202ec5b8e1e2979ec4bc1b9c7a/content/books/zizhi-tongjian/vol-293/year-0957/part-05/sources/library/songshi-263-douyan-career/source.txt", "note": "《宋史》巻二百六十三，段落 songshi-9c6e46fee832-p058270；EPUB电子本，纸本及异文待核", "id": "62939210-5895-5027-beef-29fdedad7192"}, {"title": "宋史·巻二百六十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ccb912028d375a202ec5b8e1e2979ec4bc1b9c7a/content/books/zizhi-tongjian/vol-293/year-0957/part-05/sources/library/songshi-263-douyan-music/source.txt", "note": "《宋史》巻二百六十三，段落 songshi-9c6e46fee832-p058272；EPUB电子本，纸本及异文待核", "id": "90a1b215-38c2-5887-9a88-35391748a5af"}, {"title": "宋史·巻二百六十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ccb912028d375a202ec5b8e1e2979ec4