INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "胡立", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周濮州刺史，955年六月西征时任排陈使，在威武城东与后蜀军交战失利后被俘。生卒年未载。", "biography": null, "status": "draft", "id": "28690c1d-310a-550c-a5e5-13d3b8f2377f"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "窦俨", "aliases": ["竇儼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "窦仪的弟弟，后周中书舍人。957年九月上疏建议编修礼乐、改善官员选拔、治盗与劝农等。《宋史》还记其治理六纲奏疏和考正雅乐经历，各条未明确的日期保留未知。生卒年未载。", "biography": null, "status": "draft", "id": "db93a2b0-a248-5d82-b836-c6c907b158ff"}, {"name": "窦仪", "aliases": ["竇儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟州人，后晋天平军观察判官。944年正月奉颜衎命向朝廷奏报周儒降契丹、引兵渡河及蔡行遇被俘，并向景延广说明与杨光远会合的危险。生卒年本批未核。", "biography": null, "status": "draft", "id": "9d318328-3904-5714-a390-ea527c3e9fd9"}, {"name": "张昭（五代宋初）", "aliases": ["张昭远", "張昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：张昭（五代宋初），河间推官、劝表并赞志者。", "biography": null, "status": "draft", "id": "0f1b47dc-df4b-5258-91b3-463432d576b7"}, {"name": "杨重训", "aliases": ["楊重訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "麟州杨信之子，父死后继任刺史，曾以麟州归附北汉。952年遭围攻后重新归附后周，并向夏州、府州求援。生卒年未载。", "biography": null, "status": "draft", "id": "dcdd9a95-3e4c-5ef9-b6ad-d2f8afb9ae5f"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}, {"name": "张美", "aliases": ["張美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "清河人，后周枢密院承旨。《通鉴》记955年六月任右领军大将军、权点检三司事，《旧五代史》记八月任权判三司，任职月与称号差异分别保留。早年管理澶州隶属三司的财物，曾应柴荣私人所求而供给，郭威得知后将他调到濮州。", "biography": null, "status": "draft", "id": "e0ae365f-4a51-5f92-82eb-86e617f0d42b"}, {"name": "康保裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周内殿直。957年十一月攻濠州十八里滩时，奉柴荣命率数百甲士乘骆驼涉水，参与拔寨。生卒年本段未载。", "biography": null, "status": "draft", "id": "e223b0f4-fa5c-59f0-9bcc-a47b0f3714fa"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "王审琦", "aliases": ["王審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "洛阳人，后周铁骑都指挥使，字仲宝。956年舒州人逐郭令图后，选轻骑夜袭恢复舒州。《宋史》记其先世辽西、后迁洛阳及早年在郭威军中履历，生卒年待后续补录。", "biography": null, "status": "draft", "id": "26929070-4b43-5b96-9683-d93666d18723"}, {"name": "郭廷谓", "aliases": ["郭廷謂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭城人，南唐濠州都监。957年率水军溯淮欲烧浮桥，被赵匡赞伏兵击败。生卒年未载。", "biography": null, "status": "draft", "id": "19bb918a-ace7-5a46-9480-796bbc67a61a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "遣回的怀恩军抵达成都", "start_year": 957, "end_year": 957, "time_original": "957年八月胡立东还以前，具体抵达日未载", "dynasty": "五代十国", "description": "遣回的怀恩军抵达成都。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8da231d6-7a60-5dd3-8efe-f6bca6b42686"}, {"title": "孟昶遣胡立等八十人东还，致谢并请求通好", "start_year": 957, "end_year": 957, "time_original": "957年八月癸未抵大梁以前，具体启程日未载", "dynasty": "五代十国", "description": "孟昶遣胡立等八十人东还，致谢并请求通好。", "phases": [], "location_name": "成都至大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a2642bdc-b4cd-54c4-9855-819a4d2b2133"}, {"title": "胡立等抵大梁，柴荣因孟昶抗礼不答书", "start_year": 957, "end_year": 957, "time_original": "957年八月癸未", "dynasty": "五代十国", "description": "胡立等抵大梁，柴荣因孟昶抗礼不答书。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9969d0f3-7206-55cf-a08a-3893301540e9"}, {"title": "孟昶得知柴荣不答书后愤怒", "start_year": 957, "end_year": 957, "time_original": "957年八月抵京不答以后，具体获讯日未载", "dynasty": "五代十国", "description": "孟昶得知柴荣不答书后愤怒。", "phases": [], "location_name": "后蜀朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "71214f91-3992-51f0-91a4-55e229f074f1"}, {"title": "窦俨建议编《大周通礼》与《大周正乐》", "start_year": 957, "end_year": 957, "time_original": "957年九月，具体奏日未载", "dynasty": "五代十国", "description": "窦俨建议编《大周通礼》与《大周正乐》。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3de34a7d-ae2e-5e91-8f45-baee69111d12"}, {"title": "窦俨建议荐举宰相人选、先试任政事再考察授官", "start_year": 957, "end_year": 957, "time_original": "957年九月奏疏", "dynasty": "五代十国", "description": "窦俨认为晚唐以来轻授宰相高衔，求官者竞进、任职后又容默保身。他建议宰相荐举指定官阶以上人选，皇帝熟知者直接任用；不熟知者先以本官权知政事，满一年后考察其履职，再按能力与原官阶正式授职或继续试任。不称职者解除政事、追责荐举人。这是选拔方案，不是本日已任命名单。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "964c90e2-4b9c-5689-8c91-a96a2f042e33"}, {"title": "窦俨建议让有官无职者外任试事，按政绩升黜", "start_year": 957, "end_year": 957, "time_original": "957年九月奏疏", "dynasty": "五代十国", "description": "窦俨建议让有官无职者外任试事，按政绩升黜。", "phases": [], "location_name": "后周官僚体系", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ad1da0d5-f427-5290-b668-99588b773c44"}, {"title": "窦俨建议奖励盗贼互告、按亲属首告宽免", "start_year": 957, "end_year": 957, "time_original": "957年九月奏疏", "dynasty": "五代十国", "description": "窦俨建议盗贼互相揭告，以所告者财产的一半赏告发者；若由亲属代为报告，则处罚同伙、赦免所报告者。这里记录的是提案，没有记各项已经实行或盗贼已经无法聚集。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "33d92617-c114-51ab-aaef-9b9b46a08a98"}, {"title": "窦俨以新郑义营治盗为例，建议他县仿行", "start_year": 957, "end_year": 957, "time_original": "957年九月奏疏；新郑既行做法具体起始年未载", "dynasty": "五代十国", "description": "窦俨称新郑乡村设义营与将佐，一户为盗连累全村，一户被盗追责一将；发盗时鸣鼓举火、丁壮集结。他认为新郑治盗有效，建议他县仿行。奏疏所举旧做法与本次推广请求分清，不写其他县已经实施，也不把他的效果判断当独立统计。", "phases": [], "location_name": "新郑及建议推广地区", "location