 "李重进攻破濠州南关城", "start_year": 957, "end_year": 957, "time_original": "957年十一月戊子攻滩之后、癸巳攻城以前，具体日未独载", "dynasty": "五代十国", "description": "李重进攻破濠州南关城。", "phases": [], "location_name": "濠州南关城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "73988027-6619-5043-a8f9-048c75330906"}, {"title": "王审琦攻破濠州水寨", "start_year": 957, "end_year": 957, "time_original": "957年十一月癸巳", "dynasty": "五代十国", "description": "王审琦攻破濠州水寨。", "phases": [], "location_name": "濠州水寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bb367c2b-27cb-52ba-b99a-fc320fdcc58a"}, {"title": "周水军拔除河中巨木，烧七十余战船并攻羊马城", "start_year": 957, "end_year": 957, "time_original": "957年十一月癸巳", "dynasty": "五代十国", "description": "南唐在城北屯数百战船、植巨木阻河。柴荣令水军攻拔巨木，焚船七十余艘、斩首二千余级，又攻破羊马城，史书称城中震恐。船数和人首分开记录，羊马城为外围防御设施，不写成濠州主城本日已降。", "phases": [], "location_name": "濠州北淮河及羊马城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "09d4d921-933d-5316-bb9e-757c5936d37a"}, {"title": "郭廷谓怕家族受害，请先问李璟再降，柴荣允许", "start_year": 957, "end_year": 957, "time_original": "957年十一月丙申夜", "dynasty": "五代十国", "description": "郭廷谓怕家族受害，请先问李璟再降，柴荣允许。", "phases": [], "location_name": "濠州至周营，计划遣使金陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5bbd1e8c-ef33-5b31-9a03-38dd7fe8b3d8"}, {"title": "柴荣闻泗水东有援舰，夜率水陆军出击", "start_year": 957, "end_year": 957, "time_original": "957年十一月辛丑夜", "dynasty": "五代十国", "description": "柴荣闻泗水东有援舰，夜率水陆军出击。", "phases": [], "location_name": "濠州向泗水东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "832e0632-ba1c-5c9d-85bc-b66c010784a4"}, {"title": "周军在洞口击败南唐水军，沿淮向东推进", "start_year": 957, "end_year": 957, "time_original": "957年十一月癸卯", "dynasty": "五代十国", "description": "《通鉴》记周军在洞口大破南唐军，斩首五千余级、降卒二千余人，继而向东推进。《旧五代史》该日地点作涡口、斩首五千，并补夺三百艘战船。地点与统计精度分别保留，不未经地理校核认作同一现代地点。", "phases": [], "location_name": "《通鉴》洞口；《旧五代史》涡口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "aa263ddd-f6e0-538f-9a33-0c7e88bb9464"}, {"title": "赵匡胤焚泗州南城门，攻水寨月城，柴荣督战", "start_year": 957, "end_year": 957, "time_original": "957年十一月乙巳", "dynasty": "五代十国", "description": "赵匡胤焚泗州南城门，攻水寨月城，柴荣督战。", "phases": [], "location_name": "泗州城南、水寨、月城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c6100aaa-c5ef-5556-a2ee-0c9471335d2b"}]'::jsonb)
