raft", "id": "6938ade4-0dc4-5e18-852e-43fce2e48ce2", "subject_id": "12032139-6bdb-56f1-8e6c-c61ca07196b1", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "person", "field_path": "description", "claim_text": "王审琦：攻破水寨。", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：癸巳，帝自攻濠州，王审琦拔其水寨。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "9a9957bb-96d3-5218-96fa-e29a98f2b23d", "subject_id": "26929070-4b43-5b96-9683-d93666d18723", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王审琦：攻破水寨。", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：癸巳，帝自攻濠州，王审琦拔其水寨。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "70b6dfe6-29e6-5496-97f5-25d6345edbd5", "subject_id": "ca279622-8738-584b-93ed-7be3346bc235", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "南唐在城北屯数百战船、植巨木阻河。柴荣令水军攻拔巨木，焚船七十余艘、斩首二千余级，又攻破羊马城，史书称城中震恐。船数和人首分开记录，羊马城为外围防御设施，不写成濠州主城本日已降。", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：唐人屯战船数百于城北，又植巨木于淮水以限周兵。帝命水军攻之，拔其木，焚战船七十馀艘，斩首二千馀级，又攻拔其羊马城，城中震恐。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "081953e1-6a7d-5ca5-8775-751c6b0c1a02", "subject_id": "09d4d921-933d-5316-bb9e-757c5936d37a", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "957年十一月癸巳", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：唐人屯战船数百于城北，又植巨木于淮水以限周兵。帝命水军攻之，拔其木，焚战船七十馀艘，斩首二千馀级，又攻拔其羊马城，城中震恐。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "cfe3e049-a1b6-5780-a004-601887260018", "subject_id": "09d4d921-933d-5316-bb9e-757c5936d37a", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：令水军攻破河中障碍及外围城。", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：唐人屯战船数百于城北，又植巨木于淮水以限周兵。帝命水军攻之，拔其木，焚战船七十馀艘，斩首二千馀级，又攻拔其羊马城，城中震恐。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c53b5f81-d025-5666-9aa9-9835199c5a14", "subject_id": "c9de4508-6715-5495-bd9d-09b08cddaf35", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同记七十余船、斩首二千级和攻羊马城。", "citation": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002776；EPUB电子本，纸本及异文待核", "note": "原文：癸巳，帝親率諸軍攻濠州，奪關城，破水寨，賊眾大敗，焚戰艦七十餘艘，斬首二千級，進軍攻羊馬城。；核对说明：二千与主二千余统计精度不同，不扩大为所有船尽毁；旧进军攻与主攻拔字样分源。", "status": "draft", "id": "8963ed39-2538-5dbe-bd0f-7b2411da983d", "subject_id": "09d4d921-933d-5316-bb9e-757c5936d37a", "source_id": "2985c070-3cf4-52a9-99d9-7b31623e8db2"}, {"subject_table": "event", "field_path": "description", "claim_text": "郭廷谓怕家族受害，请先问李璟再降，柴荣允许。", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：丙申夜，唐濠州团练使郭廷谓上表言：“臣家在江南，今若遽降，恐为唐所种族，请先遣使诣金陵禀命，然后出降。”帝许之。；核对说明：这时是条件请求获准，不记已正式投降；种族指诛灭家族，不作现代族群。", "status": "draft", "id": "8719b239-a340-5576-b48e-b356f9657555", "subject_id": "5bbd1e8c-ef33-5b31-9a03-38dd7fe8b3d8", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "957年十一月丙申夜", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：丙申夜，唐濠州团练使郭廷谓上表言：“臣家在江南，今若遽降，恐为唐所种族，请先遣使诣金陵禀命，然后出降。”帝许之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "797f4051-7433-5272-81c9-3854b5be8e49", "subject_id": "5bbd1e8c-ef33-5b31-9a03-38dd7fe8b3d8", "source_id": "3955ee4b-baf9-5c11-bc92-be726dde42bd"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭廷谓：上表称忧江南家人，请求先向李璟禀命。", "citation": "卷293·显德四年（957年八月至十一月及相关追述）·zztj-v293-y0957-p036·原文件第100行", "note": "原文：丙申夜，唐濠州团练使郭廷谓上表言：“臣家在江南，今若遽降，恐为唐所种族，请先遣使诣金陵禀命，然后出降。”帝许之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "11